  "legal_owner": {
    "status": "established",
    "names": ["WP Company LLC"],
    "citations": [
      {
        "url": "https://fliphtml5.com/ghjmq/hfec/",
        "quote": "The owner is WP Company LLC,"
      },
      {
        "url": "https://whca.press/wp-content/uploads/2025/10/2025.10.06-AMICUS-FOR-APPELLEE-BRIEF-2139056-filed-by-Reporters-Committee-for.pdf",
        "quote": "WP Company LLC d/b/a The Washington Post is a wholly-owned subsidiary of Nash Holdings LLC"
      }
    ]
  },
  "operator": {
    "status": "same_as_owner",
    "names": ["WP Company LLC"],
    "citations": [
      {
        "url": "https://www.washingtonpost.com/terms-of-service/?itid=mr_information_1",
        "quote": "These terms are a legal contract between you and WP Company LLC (“The Washington Post,” “we” or “us”)"
      }
    ]
  },
  "chain": [
    {
      "child": "WP Company LLC",
      "parent": "Nash Holdings LLC",
      "relation": "Wholly owned subsidiary",
      "citations": [
        {
          "url": "https://whca.press/wp-content/uploads/2025/10/2025.10.06-AMICUS-FOR-APPELLEE-BRIEF-2139056-filed-by-Reporters-Committee-for.pdf",
          "quote": "WP Company LLC d/b/a The Washington Post is a wholly-owned subsidiary of Nash Holdings LLC"
        }
      ]
    },
    {
      "child": "Nash Holdings LLC",
      "parent": "Jeffrey P. Bezos",
      "relation": "Owned by the natural person Jeffrey P. Bezos",
      "citations": [
        {
          "url": "https://whca.press/wp-content/uploads/2025/10/2025.10.06-AMICUS-FOR-APPELLEE-BRIEF-2139056-filed-by-Reporters-Committee-for.pdf",
          "quote": "Nash Holdings LLC, a holding company owned by Jeffrey P. Bezos."
        }
      ]
    }
  ],
  "ultimate_parent": {
    "status": "single",
    "names": ["Nash Holdings LLC"],
    "citations": [
      {
        "url": "https://whca.press/wp-content/uploads/2025/10/2025.10.06-AMICUS-FOR-APPELLEE-BRIEF-2139056-filed-by-Reporters-Committee-for.pdf",
        "quote": "WP Company LLC d/b/a The Washington Post is a wholly-owned subsidiary of Nash Holdings LLC, a holding company owned by Jeffrey P. Bezos."
      }
    ]
  },
  "controlling_person": {
    "status": "established",
    "names": ["Jeffrey P. Bezos (Jeff Bezos)"],
    "citations": [
      {
        "url": "https://whca.press/wp-content/uploads/2025/10/2025.10.06-AMICUS-FOR-APPELLEE-BRIEF-2139056-filed-by-Reporters-Committee-for.pdf",
        "quote": "Nash Holdings LLC, a holding company owned by Jeffrey P. Bezos."
      },
      {
        "url": "https://corporate.washingtonpost.com/about",
        "quote": "The Washington Post is owned by Jeff Bezos, executive chairman of Amazon."
      }
    ]
  },
  "leader": {
    "status": "established",
    "name": "Jeff D’Onofrio",
    "role": "Publisher and Chief Executive Officer",
    "entity": "The Washington Post",
    "citations": [
      {
        "url": "https://corporate.washingtonpost.com/about",
        "quote": "Jeff D’Onofrio\n\nPublisher & CEO"
      },
      {
        "url": "https://www.washingtonpost.com/business/2026/09/09/interim-washington-post-publisher-jeff-donofrio-serve-permanent-capacity/",
        "quote": "Jeff D’Onofrio was named publisher and CEO of The Washington Post on Wednesday following a seven-month stint serving in an interim capacity."
      }
    ]
  },
  "transactions": [
    {
      "description": "Nash Holdings LLC acquired The Washington Post Company's publishing subsidiaries, including WP Company LLC, for $250 million. The acquisition closed on October 1, 2013.",
      "status": "closed",
      "date": "2013-10-01",
      "citations": [
        {
          "url": "https://www.ghco.com/static-files/fa88319a-6162-4466-8d86-af13a725cdf9",
          "quote": "On October 1, 2013, the Company entered into a Purchase Agreement and completed the sale."
        },
        {
          "url": "https://www.ghco.com/static-files/fa88319a-6162-4466-8d86-af13a725cdf9",
          "quote": "the Purchaser acquired all the issued and outstanding equity securities of each of the entities that comprise the Publishing Subsidiaries for $250 million"
        }
      ]
    }
  ],
  "uncertainty": "As of October 4, 2026, Nash Holdings LLC is the ultimate corporate parent; Jeff Bezos is its natural-person owner and controller. The September 27, 2026 print edition's ownership statement, filed September 25, corroborates the chain but was located on a third-party reproduction; the corporate links are also documented in a court-filed disclosure. D’Onofrio became permanent publisher and CEO on September 9, 2026, rather than remaining an interim appointee."
}

